package com.andye.warmod.warhead.client.render;
import com.mojang.blaze3d.vertex.*;import net.minecraft.util.Mth;
/** Compact emissive ellipsoid engulfing the nose without camera-facing its axis. */
public final class ReentryGlowMesh{private ReentryGlowMesh(){}public static void render(PoseStack.Pose pose,VertexConsumer b,WarheadMesh.Lod lod,double heat,double shimmer){if(heat<=.01)return;int segments=lod==WarheadMesh.Lod.FAR?8:lod==WarheadMesh.Lod.MEDIUM?14:20,rings=lod==WarheadMesh.Lod.FAR?3:5;float radius=(float)Mth.lerp(heat,.45,1.75),half=(float)Mth.lerp(heat,1.4,.85);for(int ring=0;ring<rings;ring++){float v0=ring/(float)rings,v1=(ring+1)/(float)rings,a0=(v0-.5F)*Mth.PI,a1=(v1-.5F)*Mth.PI,y0=.62F+Mth.sin(a0)*half,y1=.62F+Mth.sin(a1)*half,r0=Mth.cos(a0)*radius,r1=Mth.cos(a1)*radius;for(int i=0;i<segments;i++){float u0=i/(float)segments,u1=(i+1)/(float)segments,p0=u0*Mth.TWO_PI,p1=u1*Mth.TWO_PI;int alpha=Mth.clamp((int)(255*(.34+.26*heat)*heat*shimmer),0,255);v(pose,b,r0*Mth.cos(p0),y0,r0*Mth.sin(p0),u0,v0,alpha);v(pose,b,r1*Mth.cos(p0),y1,r1*Mth.sin(p0),u0,v1,alpha);v(pose,b,r1*Mth.cos(p1),y1,r1*Mth.sin(p1),u1,v1,alpha);v(pose,b,r0*Mth.cos(p1),y0,r0*Mth.sin(p1),u1,v0,alpha);}}}private static void v(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,float u,float v,int a){b.addVertex(p,x,y,z).setColor(255,250,224,a).setUv(u,v).setOverlay(0).setLight(0xF000F0).setNormal(p,x,y-.62F,z);}}
